const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
const timestamp = Date.now();
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.`).digest('hex');
return [{ json: { ...$('Verify Signature').first().json, timestamp, signature } }];

const text = $input.first().json.choices[0].message.content;
const withoutThoughts = text.replace(/<thought>[\s\S]*?<\/thought>/gi, '');
const cleaned = withoutThoughts.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
const parsed = JSON.parse(cleaned);
return [{ json: { leadId: $('Verify Signature').first().json.leadId, orgId: $('Verify Signature').first().json.orgId, enrollmentId: $('Verify Signature').first().json.enrollmentId, agentId: $('GET Agent Prompt (writer)').first().json.agent.id, ...parsed } }];

const res = $input.first().json;
if (res.ErrorCode !== 0) {
  throw new Error(`Postmark error ${res.ErrorCode}: ${res.Message}`);
}
return [{ json: { messageId: res.MessageID } }];

const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
const timestamp = Date.now();
const parsed = $('Parse Email JSON').first().json;
const messageId = $json.messageId;
const body = { event: 'sequence.step_sent', orgId: parsed.orgId, leadId: parsed.leadId, enrollmentId: parsed.enrollmentId, agentType: 'writer', input: { templateId: parsed.templateId }, output: { subject: parsed.subject, body: parsed.body, messageId }, nextStepDueAt: null };
const rawBody = JSON.stringify(body);
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
return [{ json: { rawBody, timestamp, signature } }];
